export const params = { rsiLow: 30, minVolRatio: 1.5, stopAtr: 2, size: 0.05 };
export const bounds = { rsiLow: { min: 10, max: 50, step: 5 }, minVolRatio: { min: 1, max: 3, step: 0.1 }, stopAtr: { min: 0.5, max: 4, step: 0.5 }, size: { min: 0.01, max: 0.1, step: 0.01 } };
export function decide(x: Input, p: typeof params): Decision {
  const rsi = x.features['ta.rsi14'];
  const vr = x.features['volume.volRatio'];
  const atr = x.features['ta.atr14'];
  if (typeof rsi !== 'number' || typeof vr !== 'number' || typeof atr !== 'number') return null;
  if (rsi < p.rsiLow && vr > p.minVolRatio) return { side: 'long', size: p.size, stop: p.stopAtr * atr };
  if (rsi > 100 - p.rsiLow) return { side: 'flat', size: 0 };
  return null;
}
